#!/usr/bin/env python3
"""Собрать базовые production-файлы 7edb202 с той же QA-сценой, восстановить свою ветку в finally."""
from pathlib import Path
import os, subprocess
M = Path('multicode')
W = M/'duckpit/build/par3/l-U'
O = M/'duckpit/build/onepit/iter8d/v6l/U'
def git(*args):
    return subprocess.check_output(['git', '-C', str(W), *args])
if git('status', '--porcelain').strip():
    raise SystemExit('Сначала сохранить правки своей ветки')
files = [x for x in git('diff', '7edb202', 'HEAD', '--name-only', '--', 'Assets').decode().splitlines() if '/Tests/' not in x]
old = {x: (W/x).read_bytes() for x in files}
try:
    for f in files:
        (W/f).write_bytes(git('show', '7edb202:'+f))
    with (O/'before-build.log').open('w') as log:
        rc = subprocess.call([str(M/'tools/scripts/heavy.sh'), str(M/'duckpit/build/farm/build.sh'), str(W)], env={**os.environ, 'SET_CURRENT':'0'}, stdout=log, stderr=subprocess.STDOUT)
    print((O/'before-build.log').read_text())
    if rc:
        raise SystemExit(rc)
finally:
    for f, data in old.items():
        (W/f).write_bytes(data)
